 public static DateOnly WorkDate(DateOnly start,int offset,string week){bool Weekend(DateOnly d)=>week=="all"?false:week=="mon-fri"?d.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday:d.DayOfWeek is DayOfWeek.Friday or DayOfWeek.Saturday;while(Weekend(start))start=start.AddDays(1);while(offset-->0){do{start=start.AddDays(1);}while(Weekend(start));}return start;}
