 var source=input["rows"]!.AsArray();J.Require(source.Count is >0 and <=500,"Import 1–500 rows",400);var existing=J.A(project,"implementationPlanRows").ToList();var items=new JsonArray();int index=0,totalAllocations=0;
 foreach(var raw in source){J.Require(raw is JsonArray,"Invalid row",400);var cells=raw!.AsArray();J.Require(cells.Count<=30&&cells.All(c=>c is null||c is JsonValue&&(c.ToString().Length<=6000))&&cells.Skip(headers.Length).All(c=>string.IsNullOrWhiteSpace(c?.ToString())),"Invalid or oversized cells",400);int row=++index+1;if(input["rowNumbers"] is JsonArray numbers){J.Require(numbers.Count==source.Count&&numbers[index-1] is JsonValue n&&n.TryGetValue<int>(out row)&&row>=2&&row<=1048576,"Invalid row numbers",400);}if(cells.All(c=>string.IsNullOrWhiteSpace(c?.ToString())))continue;
 string Get(string key){int n=Array.IndexOf(headers,SpreadsheetImports.Key(key));return n>=0&&n<cells.Count?cells[n]?.ToString().Trim()??"":"";}var errors=new JsonArray();var warnings=new JsonArray();string reference=headers.Contains("company")?Get("Company"):J.S(input,"companyId");var company=PlanningCompany.Resolve(project,reference);if(company is null)errors.Add(tracking?"Company is required and must match this project’s Project Company Master (code, name or ID)":"Project has no internal company record");if(!tracking&&Get("Company")!="")warnings.Add("Company is ignored because company-wise tracking is disabled");var moduleMap=PlanningCompany.Modules(project,company);string label=Get("ACTIVITY"),kind=Get("Row Type");if(kind=="")kind=label.StartsWith("Total",StringComparison.OrdinalIgnoreCase)?"Total":label.StartsWith("Phase ",StringComparison.OrdinalIgnoreCase)||label.StartsWith("Module wise ",StringComparison.OrdinalIgnoreCase)?"Heading":"Activity";kind=new[]{"Activity","Heading","Total"}.FirstOrDefault(k=>Same(k,kind))??kind;if(!new[]{"Activity","Heading","Total"}.Contains(kind))errors.Add("Row Type must be Activity, Heading or Total");if(label.Length is <1 or >140)errors.Add("Activity label must be 1–140 characters");
 string responsible=Get("Responsible");responsible=new[]{"Client","Us"}.FirstOrDefault(r=>Same(r,responsible))??responsible;if(kind=="Activity"&&!new[]{"Client","Us"}.Contains(responsible))errors.Add("Select Responsible: Client or Us");
 bool offsetOk=int.TryParse(Get("PLAN START"),out int offset)&&offset>=1&&offset<=3660;bool daysOk=decimal.TryParse(Get("Planned Consumption (days)"),NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out decimal days)&&days>0&&days<=500&&days*2==decimal.Truncate(days*2);bool sessionsOk=int.TryParse(Get("Planned Consumption (Sessions)"),out int sessions)&&sessions>0&&sessions<=1000;
