 if(kind=="Activity"&&responsible=="Us"&&activity is null)errors.Add("Choose an active New Implementation Activity Code");if(kind=="Activity"&&module!="General"&&(!(moduleMap?.ContainsKey(module)??false)||!J.A(state.Settings,"moduleMaster").Any(m=>J.S(m,"name")==module&&J.B(m,"active",true))))errors.Add("Choose an active module selected on this company");
 string mode=Get("Work Mode")==""?"Onsite":Get("Work Mode"),charge=Get("Hours Classification")==""?"Client":Get("Hours Classification");if(!new[]{"Onsite","Offsite"}.Contains(mode))errors.Add("Work Mode must be Onsite or Offsite");if(!new[]{"Client","Internal"}.Contains(charge))errors.Add("Hours Classification must be Client or Internal");if(Get("Notes").Length>2000)errors.Add("Notes exceed 2000 characters");if(existing.Any(r=>(!tracking||J.S(r,"companyId")==J.S(company,"id"))&&Same(J.S(r,"label"),label)&&J.S(r,"kind")==kind&&J.N(r,"offset")==offset))errors.Add("This plan row already exists for this company; no duplicate schedules will be created");
 var p=new JsonObject{["id"]=Guid.NewGuid().ToString(),["companyId"]=J.S(company,"id"),["label"]=label,["kind"]=kind,["offset"]=offset,["days"]=days,["sessions"]=sessions,["responsible"]=responsible,["people"]=new JsonArray(people.Select(m=>(JsonNode?)JsonValue.Create(J.S(m,"id"))).ToArray()),["module"]=module,["activityId"]=J.S(activity,"id"),["activityName"]=J.S(activity,"name"),["activityCode"]=J.S(activity,"code"),["mode"]=mode,["charge"]=charge,["notes"]=Get("Notes"),["baselineDate"]=J.S(input,"baselineDate"),["workWeek"]=week,["status"]="To do",["start"]=offsetOk?WorkDate(baseline,offset-1,week).ToString("yyyy-MM-dd"):"",["finish"]=offsetOk&&daysOk?WorkDate(baseline,offset-1+(int)decimal.Ceiling(days)-1,week).ToString("yyyy-MM-dd"):""};
 if(kind=="Activity"&&responsible=="Us"&&daysOk){int allocations=(int)decimal.Ceiling(days)*people.Count;totalAllocations+=allocations;if(allocations>1000)errors.Add("Maximum 1000 daily allocations per activity; split this activity");if(people.Count>1)warnings.Add("Each employee receives the full duration; plan effort counted once. Confirm client deductions when updating actuals.");}if(kind!="Activity")warnings.Add("Display row only: excluded from tasks, allocations and effort totals");if(responsible=="Client")warnings.Add("Client dependency: excluded from employee allocations and our man-day consumption");
 items.Add(new JsonObject{["row"]=row,["display"]=new JsonArray(columns.Select(c=>(JsonNode?)JsonValue.Create(c=="Company"?(company is null?Get(c):J.S(company,"id")):Get(c))).ToArray()),["payload"]=p,["errors"]=errors,["warnings"]=warnings});}
 J.Require(items.Count>0,"No data rows found",400);var list=items.OfType<JsonObject>().ToList();foreach(var item in list){var p=item["payload"]!;if(list.Count(i=>Same(J.S(i["payload"],"label"),J.S(p,"label"))&&J.S(i["payload"],"kind")==J.S(p,"kind")&&J.S(i["payload"],"companyId")==J.S(p,"companyId")&&J.N(i["payload"],"offset")==J.N(p,"offset"))>1)item["errors"]!.AsArray().Add("Duplicate label / Plan Start / Row Type in file");if(totalAllocations>5000)item["errors"]!.AsArray().Add("Maximum 5000 generated allocations per batch; split this plan");}foreach(var group in list.GroupBy(i=>J.S(i["payload"],"companyId")))J.Require(existing.Count(r=>J.S(r,"companyId")==group.Key)+group.Count()<=500,"Maximum 500 plan rows per company",400);
 return new JsonObject{["kind"]="implementation-plan",["revision"]=state.Revision,["columns"]=new JsonArray(columns.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["items"]=items,["validCount"]=list.Count(i=>i["errors"]!.AsArray().Count==0),["invalidCount"]=list.Count(i=>i["errors"]!.AsArray().Count>0)};
 }
 public static JsonObject Apply(Snapshot state,Policy policy,JsonObject input){var preview=Validate(state,policy,input);J.Require(J.N(preview,"invalidCount")==0,"Correct all plan errors before saving. No rows saved",400);var project=J.Clone(state.Records["project:"+J.S(input,"projectId")]);var rows=(project["implementationPlanRows"]??=new JsonArray()).AsArray();var changes=new JsonArray();int count=0;
 foreach(var item in J.A(preview,"items")){var r=J.Clone(item["payload"]!.AsObject());if(J.S(r,"kind")=="Activity"&&J.S(r,"responsible")=="Us"){string taskId=Guid.NewGuid().ToString();r["taskId"]=taskId;var people=r["people"]!.AsArray();var allocations=new JsonArray();int sessions=(int)J.N(r,"sessions"),day=0;while(sessions>0){int units=Math.Min(2,sessions);string date=WorkDate(J.Day(J.S(r,"start")),day++,J.S(r,"workWeek")).ToString("yyyy-MM-dd"),team=people.Count>1?Guid.NewGuid().ToString():"";foreach(var person in people)allocations.Add(new JsonObject{["id"]=Guid.NewGuid().ToString(),["assignee"]=person!.ToString(),["date"]=date,["plannedHours"]=units*4m,["typeId"]="implementation",["workMode"]=J.S(r,"mode"),["chargeType"]=J.S(r,"charge"),["instructions"]=J.S(r,"notes"),["status"]="Planned",["actualHours"]=0m,["actualWorkDate"]="",["actualHistory"]=new JsonArray(),["completionRemarks"]="",["billableToClient"]=true,["billingConfirmed"]=false,["billingHistory"]=new JsonArray(),["weeklyPlanId"]=J.S(r,"id"),["weeklyWeek"]=J.Day(date).AddDays(-(((int)J.Day(date).DayOfWeek+6)%7)).ToString("yyyy-MM-dd"),["teamGroupId"]=team,["implementationPlanRowId"]=J.S(r,"id")});sessions-=units;}
 var task=new JsonObject{["id"]=taskId,["project"]=J.S(project,"id"),["companyId"]=J.S(r,"companyId"),["module"]=J.S(r,"module"),["typeId"]="implementation",["title"]=J.S(r,"activityName"),["activityId"]=J.S(r,"activityId"),["assignee"]=people[0]!.ToString(),["plannedStart"]=J.S(r,"start"),["plannedFinish"]=J.S(r,"finish"),["due"]=J.S(r,"finish"),["plannedSessions"]=r["sessions"]!.DeepClone(),["priority"]="Medium",["notes"]=J.S(r,"notes"),["status"]="To do",["completion"]=0,["actualStart"]="",["actualFinish"]="",["sessions"]=new JsonArray(),["history"]=new JsonArray(),["visits"]=0,["allocations"]=allocations,["implementationPlanRowId"]=J.S(r,"id")};changes.Add(new JsonObject{["kind"]="task",["id"]=taskId,["payload"]=task});count+=allocations.Count;}rows.Add(r);}
